mapper.select:
SELECT AUTHRT_CD, AUTHRT_NM, AUTHRT_CN, USE_YN, REG_DT, MDFCN_DT

ORDER BY REG_DT DESC
LIMIT #{offset}, #{limit}

SELECT AUTHRT_CD, AUTHRT_NM, AUTHRT_CN, USE_YN, REG_DT, MDFCN_DT
FROM AUTH_GRP
WHERE AUTHRT_CD = #{authrtCd}

mapper.update:
UPDATE AUTH_GRP
SET AUTHRT_NM = #{authrtNm}, AUTHRT_CN = #{authrtCn}, USE_YN = #{useYn}, MDFCN_DT = NOW()
WHERE AUTHRT_CD = #{authrtCd}
